module accu (
	input clk, rst_n, valid_in,
	input [7:0] data_in,
	output reg valid_out,
	output reg [9:0] data_out
);
	reg [1:0] cnt;

	// Sequential logic block triggered on the rising edge of clk or falling edge of rst_n
	always @(posedge clk or negedge rst_n) begin
		if (!rst_n) begin
			// Reset condition: Set all registers to zero
			cnt <= 0;
			data_out <= 0;
			valid_out <= 0;
		end else begin
			// Check if valid_in is high
			if (valid_in == 1) begin
				// Increment counter
				cnt <= cnt + 1;

				// Add current data_in value to accumulator
				data_out <= data_out + data_in;

				// Check if counter has reached 4
				if (cnt == 4) begin
					// Set valid_out to 1 when counter reaches 4
					valid_out <= 1;

					// Reset counter after reaching 4
					cnt <= 0;
				end else begin
					// Set valid_out to 0 otherwise
					valid_out <= 0;
				end
			end else begin
				// Set valid_out to 0 if valid_in is not high
				valid_out <= 0;
			end
		end
	end

endmodule
